 // Animate inside positioning groups so SVG coordinates remain intact.
 world.querySelectorAll('.person,.message').forEach((group,i)=>{const inner=document.createElementNS('http://www.w3.org/2000/svg','g');while(group.firstChild)inner.appendChild(group.firstChild);group.appendChild(inner);const dx=12+Math.random()*18,dy=10+Math.random()*20;animations.push(inner.animate([{transform:'translate(0,0)'},{transform:'translate('+dx+'px,-'+dy+'px)'},{transform:'translate(-'+dx/2+'px,'+dy/2+'px)'},{transform:'translate(0,0)'}],{duration:4500+Math.random()*3500,delay:-i*900,iterations:Infinity,easing:'ease-in-out'}));});
 function sync(){document.body.classList.toggle('motion-paused',paused);animations.forEach(a=>paused?a.pause():a.play());toggle.setAttribute('aria-pressed',String(paused));toggle.textContent=paused?@json($ar?'تشغيل الحركة':'Play motion'):@json($ar?'إيقاف الحركة':'Pause motion');}sync();toggle.onclick=()=>{paused=!paused;sync()};reduce.addEventListener('change',e=>{paused=e.matches;sync()});
 world.querySelectorAll('.citizen').forEach(person=>{let timer;const greet=()=>{person.classList.add('greet');clearTimeout(timer);timer=setTimeout(()=>person.classList.remove('greet'),2200)};person.addEventListener('click',greet);person.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();greet()}})});
 let queued=false;function scrollMotion(){queued=false;if(paused)return;const r=world.getBoundingClientRect();svg.style.setProperty('--sy',Math.max(-30,Math.min(30,-r.top*.08))+'px');svg.style.setProperty('--turn','0deg');world.querySelector('.trees')?.style.setProperty('--mx',Math.max(-22,Math.min(22,-r.top*.06))+'px');document.querySelectorAll('.mini-art').forEach(el=>el.style.setProperty('--lift',Math.max(-16,Math.min(16,(innerHeight/2-el.getBoundingClientRect().top)*.045))+'px'));}
 addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(scrollMotion)}},{passive:true});world.addEventListener('pointermove',e=>{if(paused||e.pointerType==='touch')return;const r=world.getBoundingClientRect();svg.style.setProperty('--mx',((e.clientX-r.left)/r.width-.5)*35+'px')});world.addEventListener('pointerleave',()=>svg.style.setProperty('--mx','0px'));
 })();
 </script>
</body></html>
